+        "a","an","the","and","or","but","is","are","was","were","be","been","being",
+        "have","has","had","do","does","did","will","would","shall","should","may",
+        "might","must","can","could","in","on","at","to","for","of","with","by",
+        "from","as","into","through","during","before","after","above","below",
+        "between","out","off","over","under","again","further","then","once","it",
+        "its","this","that","these","those","i","me","my","we","our","you","your",
+        "he","him","his","she","her","they","them","their","what","which","who",
+        "whom","when","where","why","how","not","no","nor","so","if","about","up",
+        "very","just","also","than"
+    };
+
+    public string Summarize(string text, int maxSentences)
+    {
+        var sentences = SplitIntoSentences(text);
+
+        if (sentences.Count <= maxSentences)
+            return string.Join(" ", sentences);
+
+        var wordFrequencies = BuildWordFrequencies(sentences);
+        var scoredSentences = sentences
+            .Select((sentence, index) => (Index: index, Sentence: sentence, Score: ScoreSentence(sentence, wordFrequencies)))
+            .OrderByDescending(s => s.Score)
+            .Take(maxSentences)
+            .OrderBy(s => s.Index) // preserve original order
+            .Select(s => s.Sentence);
+
+        return string.Join(" ", scoredSentences);
+    }
+
+    private static List<string> SplitIntoSentences(string text)
+    {
+        return text.Split(['.', '!', '?'], StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
+            .Where(s => s.Split(' ', StringSplitOptions.RemoveEmptyEntries).Length >= 3)
+            .Select(s => s.TrimEnd() + ".")
+            .ToList();
+    }
+
+    private static Dictionary<string, int> BuildWordFrequencies(List<string> sentences)
+    {
+        var freq = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
+        foreach (var sentence in sentences)
+        {
+            foreach (var word in GetWords(sentence))
+            {
+                if (!StopWords.Contains(word))
+                    freq[word] = freq.GetValueOrDefault(word) + 1;
+            }
+        }
+        return freq;
+    }
+
+    private static double ScoreSentence(string sentence, Dictionary<string, int> wordFrequencies)
+    {
+        var words = GetWords(sentence);
+        if (words.Length == 0) return 0;
+
+        double score = 0;
+        foreach (var word in words)
+        {
+            if (wordFrequencies.TryGetValue(word, out int freq))
+                score += freq;
+        }
+        return score / words.Length;
+    }
+
+    private static string[] GetWords(string text) =>
+        text.Split([' ', '\t', '\n', '\r', ',', ';', ':', '"', '\'', '(', ')', '[', ']'],
+            StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
+}
